const response = $input.first().json || {};
const content = response.content || response || {};
const towns = Array.isArray(content.towns) ? content.towns : [];

if (!Array.isArray(towns) || towns.length === 0) {
  throw new Error('PSE&G outage summary returned no town records. Notification was not sent and the previous baseline was preserved.');
}

const EXPECTED_TOWNS = [
  'Bayonne',
  'East Newark',
  'Guttenberg',
  'Harrison',
  'Hoboken',
  'Jersey City',
  'Kearny',
  'North Bergen',
  'Secaucus',
  'Union City',
  'Weehawken',
  'West New York',
];

const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
const HUDSON_REPORT_URL = 'https://outagecenter.pseg.com/reports/e2d9e8d8-113c-423b-af59-0de1bc440376?c=External&o=View_by_county';

const firstDefined = (...values) => values.find(v => v !== undefined && v !== null && v !== '');

const numOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const textOrNull = (value) => {
  if (value === undefined || value === null) return null;
  const s = String(value).trim();
  return s ? s : null;
};

const normalizeTown = (value) => {
  let s = String(value || '')
    .toUpperCase()
    .replace(/[.,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const exact = {
    'BAYONNE': 'Bayonne',
    'EAST NEWARK': 'East Newark',
    'GUTTENBERG': 'Guttenberg',
    'HARRISON': 'Harrison',
    'HOBOKEN': 'Hoboken',
    'JERSEY CITY': 'Jersey City',
    'KEARNY': 'Kearny',
    'NORTH BERGEN': 'North Bergen',
    'SECAUCUS': 'Secaucus',
    'UNION CITY': 'Union City',
    'WEEHAWKEN': 'Weehawken',
    'WEST NEW YORK': 'West New York',
  };

  // Preserve municipality names that legitimately end in "City" (Jersey City, Union City).
  if (exact[s]) return exact[s];

  // Remove a municipal-type suffix only after checking exact municipality names.
  s = s
    .replace(/\s+(TOWNSHIP|TWP|TOWN|CITY|BOROUGH|BORO|VILLAGE)$/i, '')
    .replace(/\s+/g, ' ')
    .trim();

  return exact[s] || s.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
};

const formatDate = (value) => {
  if (!value) return '--';
  const raw = String(value).trim();
  if (!raw) return '--';

  if (/assess|reassess|pending|unknown|not available|tbd/i.test(raw)) {
    return raw.toUpperCase().slice(0, 11);
  }

  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw.toUpperCase().slice(0, 11);

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(d);

  const p = Object.fromEntries(parts.map(x => [x.type, x.value]));
  return `${p.month}/${p.day} ${p.hour}:${p.minute}`;
};

const nowEastern = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    month: '2-digit',
    day: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date());
  const p = Object.fromEntries(parts.map(x => [x.type, x.value]));
  return `${p.month}/${p.day}/${p.year} ${p.hour}:${p.minute} ET`;
};

const clip = (value, width) => {
  const s = String(value ?? '--');
  return s.length > width ? s.slice(0, width) : s;
};

const left = (value, width) => clip(value, width).padEnd(width, ' ');
const right = (value, width) => clip(value, width).padStart(width, ' ');

const fmtInt = (value) => value === null ? '--' : Math.round(value).toLocaleString('en-US');
const fmtPct = (value) => value === null ? '--' : `${Number(value).toFixed(1)}%`;

const isHudsonRecord = (loc) => {
  const county = String(firstDefined(loc.county, loc.displayCounty, '') || '').toUpperCase();
  const name = normalizeTown(firstDefined(loc.displayTown, loc.town, loc.name, ''));
  return county.includes('HUDSON') || EXPECTED_TOWNS.includes(name);
};

const hudsonRecords = towns.filter(isHudsonRecord);
const byTown = new Map();

for (const loc of hudsonRecords) {
  const canonical = normalizeTown(firstDefined(loc.displayTown, loc.town, loc.name, ''));
  if (!EXPECTED_TOWNS.includes(canonical)) continue;
  byTown.set(canonical, loc);
}

const rows = EXPECTED_TOWNS.map(townName => {
  const loc = byTown.get(townName);
  if (!loc) {
    return {
      town: townName,
      sourceTown: null,
      dataStatus: 'NO DATA',
      customersOut: null,
      customersServed: null,
      percentOut: null,
      earliestCurrentOutage: null,
      etrEarliest: null,
      etrLatest: null,
      numberOfJobs: null,
      jobsBeingWorked: null,
      numberOfCircuits: null,
      pendingDamage: null,
      confirmedPoles: null,
      confirmedTrees: null,
      confirmedRoadsBlocked: null,
    };
  }

  return {
    town: townName,
    sourceTown: textOrNull(firstDefined(loc.town, loc.displayTown)),
    dataStatus: 'OK',
    customersOut: numOrNull(loc.customersOut),
    customersServed: numOrNull(loc.customersServed),
    percentOut: numOrNull(loc.percentOut),
    earliestCurrentOutage: textOrNull(loc.earliestCurrentOutage),
    etrEarliest: textOrNull(loc.etrEarliest),
    etrLatest: textOrNull(firstDefined(loc.etrLatest, loc.latestEtr, loc.etrLatestTime)),
    numberOfJobs: numOrNull(loc.numberOfJobs),
    jobsBeingWorked: numOrNull(firstDefined(loc.numberOfJobsBeingWorked, loc.jobsBeingWorked, loc.workingJobs)),
    numberOfCircuits: numOrNull(loc.numberOfCircuits),
    pendingDamage: numOrNull(loc.pendingDamage),
    confirmedPoles: numOrNull(loc.confirmedPoles),
    confirmedTrees: numOrNull(loc.confirmedTrees),
    confirmedRoadsBlocked: numOrNull(firstDefined(loc.confirmedRoadsBlocked, loc.roadsBlocked, loc.confirmedRoads)),
  };
});

const totalOutages = rows.reduce((sum, row) => sum + (row.customersOut ?? 0), 0);
const missingCount = rows.filter(row => row.dataStatus !== 'OK').length;

const staticData = $getWorkflowStaticData('global');
const previous = staticData.psegHudsonStateV4 || null;

const currentState = {
  rows: Object.fromEntries(rows.map(row => [row.town, row])),
  totalOutages,
  missingCount,
};

// First run stores the baseline AND sends a status notification.
// This also makes manual n8n testing immediately visible in ntfy.
if (!previous) {
  staticData.psegHudsonStateV4 = currentState;

  const headers = [
    `${left('', 1)} ${left('TOWN', 14)} ${right('OUT', 5)} ${right('SERVED', 7)} ${right('%', 6)} ${left('START', 11)} ${left('ETR EARLY', 11)} ${left('ETR LATE', 11)} ${right('JOB', 3)} ${right('WRK', 3)} ${right('CIR', 3)} ${right('PEND', 4)} ${right('POL', 3)} ${right('TREE', 4)} ${right('ROAD', 4)} ${left('STATUS', 7)}`,
    `${'-'.repeat(1)} ${'-'.repeat(14)} ${'-'.repeat(5)} ${'-'.repeat(7)} ${'-'.repeat(6)} ${'-'.repeat(11)} ${'-'.repeat(11)} ${'-'.repeat(11)} ${'-'.repeat(3)} ${'-'.repeat(3)} ${'-'.repeat(3)} ${'-'.repeat(4)} ${'-'.repeat(3)} ${'-'.repeat(4)} ${'-'.repeat(4)} ${'-'.repeat(7)}`,
  ];

  const tableRows = rows.map(row => {
    const status = row.dataStatus !== 'OK'
      ? 'NO DATA'
      : ((row.customersOut || 0) > 0 ? 'OUT' : 'OK');

    return `${left(' ', 1)} ${left(row.town, 14)} ${right(fmtInt(row.customersOut), 5)} ${right(fmtInt(row.customersServed), 7)} ${right(fmtPct(row.percentOut), 6)} ${left(formatDate(row.earliestCurrentOutage), 11)} ${left(formatDate(row.etrEarliest), 11)} ${left(formatDate(row.etrLatest), 11)} ${right(fmtInt(row.numberOfJobs), 3)} ${right(fmtInt(row.jobsBeingWorked), 3)} ${right(fmtInt(row.numberOfCircuits), 3)} ${right(fmtInt(row.pendingDamage), 4)} ${right(fmtInt(row.confirmedPoles), 3)} ${right(fmtInt(row.confirmedTrees), 4)} ${right(fmtInt(row.confirmedRoadsBlocked), 4)} ${left(status, 7)}`;
  });

  let message = '';
  message += `**PSEG HUDSON COUNTY**\n`;
  message += `Updated: ${nowEastern()}\n`;
  message += `Affected: **${totalOutages.toLocaleString('en-US')}** | Initial monitor status | Missing towns: **${missingCount}**\n\n`;
  message += '```\n';
  message += [...headers, ...tableRows].join('\n');
  message += '\n```';

  const ntfyPayload = {
    topic: '[REDACTED]',
    title: totalOutages > 0 ? 'PSEG - Monitor Started: Active Outage' : 'PSEG - Monitor Started',
    message,
    priority: totalOutages > 0 ? 5 : 3,
    tags: totalOutages > 0 ? ['warning', 'zap'] : ['white_check_mark', 'zap'],
    markdown: true,
    click: PSEG_MAP_URL,
    actions: [
      {
        action: 'view',
        label: 'PSEG Map',
        url: PSEG_MAP_URL,
        clear: false,
      },
      {
        action: 'view',
        label: 'Hudson Summary',
        url: HUDSON_REPORT_URL,
        clear: false,
      },
    ],
  };

  return [{
    json: {
      shouldSend: true,
      reason: 'Initial baseline stored and initial status notification requested.',
      totalOutages,
      missingCount,
      ntfyPayload,
    }
  }];
}

const previousRows = previous.rows || {};
const changedTowns = [];
const etrChangedTowns = [];

for (const row of rows) {
  const oldRow = previousRows[row.town] || null;
  if (JSON.stringify(oldRow) !== JSON.stringify(row)) changedTowns.push(row.town);

  if (oldRow) {
    if (
      oldRow.etrEarliest !== row.etrEarliest ||
      oldRow.etrLatest !== row.etrLatest
    ) {
      etrChangedTowns.push(row.town);
    }
  }
}

const removedPreviousTowns = Object.keys(previousRows).filter(t => !currentState.rows[t]);
for (const town of removedPreviousTowns) {
  if (!changedTowns.includes(town)) changedTowns.push(town);
}

const previousTotal = Number(previous.totalOutages || 0);
const delta = totalOutages - previousTotal;
const stateChanged = changedTowns.length > 0 || Number(previous.missingCount || 0) !== missingCount;

// Always update the stored snapshot after a successful parse.
staticData.psegHudsonStateV4 = currentState;

if (!stateChanged) {
  return [{
    json: {
      shouldSend: false,
      reason: 'No meaningful Hudson County PSE&G data changed.',
      totalOutages,
      missingCount,
      ntfyPayload: null,
    }
  }];
}

let title = 'PSEG - Outage Update';
let priority = 4;
let tags = ['zap'];

if (previousTotal === 0 && totalOutages > 0) {
  title = 'PSEG - New Outage';
  priority = 5;
  tags = ['warning', 'zap'];
} else if (previousTotal > 0 && totalOutages === 0) {
  title = 'PSEG - Power Restored';
  priority = 4;
  tags = ['white_check_mark', 'zap'];
} else if (delta > 0) {
  title = 'PSEG - Outage Increasing';
  priority = 5;
  tags = ['warning', 'zap'];
} else if (delta < 0) {
  title = 'PSEG - Restoration Progress';
  priority = 3;
  tags = ['chart_with_downwards_trend', 'zap'];
} else if (etrChangedTowns.length > 0) {
  title = 'PSEG - Restoration Time Updated';
  priority = 4;
  tags = ['clock1', 'zap'];
} else if (missingCount > 0 && Number(previous.missingCount || 0) !== missingCount) {
  title = 'PSEG - Data Coverage Changed';
  priority = 4;
  tags = ['warning', 'zap'];
}

const deltaText = delta > 0 ? `+${delta}` : String(delta);
const changedText = changedTowns.length ? changedTowns.join(', ') : 'None';

const headers = [
  `${left('', 1)} ${left('TOWN', 14)} ${right('OUT', 5)} ${right('SERVED', 7)} ${right('%', 6)} ${left('START', 11)} ${left('ETR EARLY', 11)} ${left('ETR LATE', 11)} ${right('JOB', 3)} ${right('WRK', 3)} ${right('CIR', 3)} ${right('PEND', 4)} ${right('POL', 3)} ${right('TREE', 4)} ${right('ROAD', 4)} ${left('STATUS', 7)}`,
  `${'-'.repeat(1)} ${'-'.repeat(14)} ${'-'.repeat(5)} ${'-'.repeat(7)} ${'-'.repeat(6)} ${'-'.repeat(11)} ${'-'.repeat(11)} ${'-'.repeat(11)} ${'-'.repeat(3)} ${'-'.repeat(3)} ${'-'.repeat(3)} ${'-'.repeat(4)} ${'-'.repeat(3)} ${'-'.repeat(4)} ${'-'.repeat(4)} ${'-'.repeat(7)}`,
];

const tableRows = rows.map(row => {
  const changed = changedTowns.includes(row.town) ? '*' : ' ';
  const status = row.dataStatus !== 'OK'
    ? 'NO DATA'
    : ((row.customersOut || 0) > 0 ? 'OUT' : 'OK');

  return `${left(changed, 1)} ${left(row.town, 14)} ${right(fmtInt(row.customersOut), 5)} ${right(fmtInt(row.customersServed), 7)} ${right(fmtPct(row.percentOut), 6)} ${left(formatDate(row.earliestCurrentOutage), 11)} ${left(formatDate(row.etrEarliest), 11)} ${left(formatDate(row.etrLatest), 11)} ${right(fmtInt(row.numberOfJobs), 3)} ${right(fmtInt(row.jobsBeingWorked), 3)} ${right(fmtInt(row.numberOfCircuits), 3)} ${right(fmtInt(row.pendingDamage), 4)} ${right(fmtInt(row.confirmedPoles), 3)} ${right(fmtInt(row.confirmedTrees), 4)} ${right(fmtInt(row.confirmedRoadsBlocked), 4)} ${left(status, 7)}`;
});

let message = '';
message += `**PSEG HUDSON COUNTY**\n`;
message += `Updated: ${nowEastern()}\n`;
message += `Affected: **${totalOutages.toLocaleString('en-US')}** | Change: **${deltaText}** | Missing towns: **${missingCount}**\n`;
message += `Changed: ${changedText}\n\n`;
message += '```\n';
message += [...headers, ...tableRows].join('\n');
message += '\n```\n';
message += `* = changed since the previous check`;

const ntfyPayload = {
  topic: '[REDACTED]',
  title,
  message,
  priority,
  tags,
  markdown: true,
  click: PSEG_MAP_URL,
  actions: [
    {
      action: 'view',
      label: 'PSEG Map',
      url: PSEG_MAP_URL,
      clear: false,
    },
    {
      action: 'view',
      label: 'Hudson Summary',
      url: HUDSON_REPORT_URL,
      clear: false,
    },
  ],
};

return [{
  json: {
    shouldSend: true,
    title,
    changedTowns,
    etrChangedTowns,
    totalOutages,
    previousTotal,
    delta,
    missingCount,
    ntfyPayload,
  }
}];

const response = $input.first().json ?? {};
const content = response.content ?? response;
const towns = Array.isArray(content.towns) ? content.towns : [];

if (!towns.length) {
  throw new Error(
    'PSE&G outage summary returned no town records. No notification was sent and the previous baseline was preserved.'
  );
}

const EXPECTED_TOWNS = [
  'Bayonne',
  'East Newark',
  'Guttenberg',
  'Harrison',
  'Hoboken',
  'Jersey City',
  'Kearny',
  'North Bergen',
  'Secaucus',
  'Union City',
  'Weehawken',
  'West New York',
];

const STATE_KEY = 'psegHudsonStateV5';
const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
const HUDSON_REPORT_URL =
  'https://outagecenter.pseg.com/reports/e2d9e8d8-113c-423b-af59-0de1bc440376?c=External&o=View_by_county';

const firstDefined = (...values) =>
  values.find((value) => value !== undefined && value !== null && value !== '');

const toNumber = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const toText = (value) => {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text || null;
};

const fmtInt = (value) =>
  value === null || value === undefined
    ? '--'
    : Math.round(value).toLocaleString('en-US');

const customerWord = (count) => (Number(count) === 1 ? 'customer' : 'customers');

const municipalityWord = (count) =>
  Number(count) === 1 ? 'municipality' : 'municipalities';

const normalizeTown = (value) => {
  let town = String(value ?? '')
    .toUpperCase()
    .replace(/[.,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const exact = {
    BAYONNE: 'Bayonne',
    'EAST NEWARK': 'East Newark',
    GUTTENBERG: 'Guttenberg',
    HARRISON: 'Harrison',
    HOBOKEN: 'Hoboken',
    'JERSEY CITY': 'Jersey City',
    KEARNY: 'Kearny',
    'NORTH BERGEN': 'North Bergen',
    SECAUCUS: 'Secaucus',
    'UNION CITY': 'Union City',
    WEEHAWKEN: 'Weehawken',
    'WEST NEW YORK': 'West New York',
  };

  if (exact[town]) return exact[town];

  town = town
    .replace(/\s+(TOWNSHIP|TWP|TOWN|CITY|BOROUGH|BORO|VILLAGE)$/i, '')
    .replace(/\s+/g, ' ')
    .trim();

  return (
    exact[town] ||
    town.toLowerCase().replace(/\b\w/g, (letter) => letter.toUpperCase())
  );
};

const formatTime = (value) => {
  if (!value) return '--';

  const raw = String(value).trim();
  if (!raw) return '--';

  if (/assess|reassess|pending|unknown|not available|tbd/i.test(raw)) {
    return raw.toUpperCase();
  }

  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw.toUpperCase();

  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(date);
};

const nowEastern = () =>
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(new Date());

const percentOutText = (row) => {
  const out = Number(row.customersOut);
  const served = Number(row.customersServed);

  if (!Number.isFinite(out) || !Number.isFinite(served) || served <= 0) {
    return null;
  }

  const pct = (out / served) * 100;

  if (out > 0 && pct < 0.1) return '<0.1%';
  return `${pct.toFixed(1)}%`;
};

const operationalLine = (row) => {
  const parts = [];

  if (row.numberOfJobs !== null) {
    parts.push(`Jobs ${fmtInt(row.numberOfJobs)}`);
  }

  if (row.jobsBeingWorked !== null) {
    parts.push(`Working ${fmtInt(row.jobsBeingWorked)}`);
  }

  if (row.numberOfCircuits !== null) {
    parts.push(`Circuits ${fmtInt(row.numberOfCircuits)}`);
  }

  return parts.join(' | ');
};

const damageLine = (row) => {
  const parts = [];

  const addIfPositive = (label, value) => {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) {
      parts.push(`${label} ${fmtInt(n)}`);
    }
  };

  addIfPositive('Pending', row.pendingDamage);
  addIfPositive('Pole', row.confirmedPoles);
  addIfPositive('Tree', row.confirmedTrees);
  addIfPositive('Road', row.confirmedRoadsBlocked);

  return parts.length ? `Damage: ${parts.join(' | ')}` : null;
};

const isHudsonRecord = (record) => {
  const county = String(
    firstDefined(record.county, record.displayCounty, '') ?? ''
  ).toUpperCase();

  const town = normalizeTown(
    firstDefined(record.displayTown, record.town, record.name, '')
  );

  return county.includes('HUDSON') || EXPECTED_TOWNS.includes(town);
};

const byTown = new Map();

for (const record of towns.filter(isHudsonRecord)) {
  const town = normalizeTown(
    firstDefined(record.displayTown, record.town, record.name, '')
  );

  if (EXPECTED_TOWNS.includes(town)) {
    byTown.set(town, record);
  }
}

const rows = EXPECTED_TOWNS.map((town) => {
  const record = byTown.get(town);

  if (!record) {
    return {
      town,
      dataStatus: 'NO DATA',
      customersOut: null,
      customersServed: null,
      earliestCurrentOutage: null,
      etrEarliest: null,
      etrLatest: null,
      numberOfJobs: null,
      jobsBeingWorked: null,
      numberOfCircuits: null,
      pendingDamage: null,
      confirmedPoles: null,
      confirmedTrees: null,
      confirmedRoadsBlocked: null,
    };
  }

  return {
    town,
    dataStatus: 'OK',
    customersOut: toNumber(record.customersOut),
    customersServed: toNumber(record.customersServed),
    earliestCurrentOutage: toText(record.earliestCurrentOutage),
    etrEarliest: toText(record.etrEarliest),
    etrLatest: toText(
      firstDefined(record.etrLatest, record.latestEtr, record.etrLatestTime)
    ),
    numberOfJobs: toNumber(record.numberOfJobs),
    jobsBeingWorked: toNumber(
      firstDefined(
        record.numberOfJobsBeingWorked,
        record.jobsBeingWorked,
        record.workingJobs
      )
    ),
    numberOfCircuits: toNumber(record.numberOfCircuits),
    pendingDamage: toNumber(record.pendingDamage),
    confirmedPoles: toNumber(record.confirmedPoles),
    confirmedTrees: toNumber(record.confirmedTrees),
    confirmedRoadsBlocked: toNumber(
      firstDefined(
        record.confirmedRoadsBlocked,
        record.roadsBlocked,
        record.confirmedRoads
      )
    ),
  };
});

const totalOutages = rows.reduce(
  (sum, row) => sum + (row.customersOut ?? 0),
  0
);

const missingCount = rows.filter((row) => row.dataStatus !== 'OK').length;

const currentState = {
  rows: Object.fromEntries(rows.map((row) => [row.town, row])),
  totalOutages,
  missingCount,
};

const staticData = $getWorkflowStaticData('global');
const previous = staticData[STATE_KEY] ?? null;
const previousRows = previous?.rows ?? {};
const previousTotal = Number(previous?.totalOutages ?? 0);

const changedTowns = [];
const etrChangedTowns = [];

if (previous) {
  for (const row of rows) {
    const oldRow = previousRows[row.town] ?? null;

    if (JSON.stringify(oldRow) !== JSON.stringify(row)) {
      changedTowns.push(row.town);
    }

    if (
      oldRow &&
      (oldRow.etrEarliest !== row.etrEarliest ||
        oldRow.etrLatest !== row.etrLatest)
    ) {
      etrChangedTowns.push(row.town);
    }
  }
}

const stateChanged =
  !previous ||
  changedTowns.length > 0 ||
  Number(previous?.missingCount ?? 0) !== missingCount;

// Only replace the baseline after a successful parse.
staticData[STATE_KEY] = currentState;

if (previous && !stateChanged) {
  return [
    {
      json: {
        shouldSend: false,
        reason: 'No meaningful Hudson County PSE&G data changed.',
        totalOutages,
        missingCount,
        ntfyPayload: null,
      },
    },
  ];
}

const activeRows = rows.filter(
  (row) => row.dataStatus === 'OK' && (row.customersOut ?? 0) > 0
);

const delta = previous ? totalOutages - previousTotal : 0;

const townDelta = (row) => {
  if (!previous) return 0;
  const oldRow = previousRows[row.town] ?? null;
  return (row.customersOut ?? 0) - (oldRow?.customersOut ?? 0);
};

const statusIcon = (row) => {
  if (!previous) return '🔴';

  const change = townDelta(row);

  if (change > 0) return '🔴';
  if (change < 0) return '🟡';
  if (etrChangedTowns.includes(row.town)) return '🟠';
  return '🔴';
};

const buildTitle = () => {
  if (totalOutages === 0) {
    return previousTotal > 0
      ? 'PSEG - Hudson - Power Restored'
      : 'PSEG - Hudson Clear';
  }

  if (activeRows.length === 1) {
    const row = activeRows[0];
    return `PSEG - ${row.town} - ${fmtInt(row.customersOut)} Out`;
  }

  return `PSEG - Hudson - ${fmtInt(totalOutages)} Out`;
};

const buildMessage = () => {
  const lines = [];

  if (totalOutages === 0) {
    lines.push('HUDSON COUNTY CLEAR');
    lines.push('0 customers out');

    if (previous && previousTotal > 0) {
      lines.push(`${fmtInt(previousTotal)} restored since last check`);
    }
  } else {
    lines.push(
      `${fmtInt(totalOutages)} ${customerWord(totalOutages)} out | ` +
        `${activeRows.length} active ${municipalityWord(activeRows.length)}`
    );

    if (previous && delta !== 0) {
      lines.push(`Change since last check: ${delta > 0 ? '+' : ''}${fmtInt(delta)}`);
    }

    lines.push('');

    for (const row of activeRows) {
      const pct = percentOutText(row);
      const change = townDelta(row);

      let townLine = `${statusIcon(row)} ${row.town.toUpperCase()}`;
      if (previous && change !== 0) {
        townLine += ` (${change > 0 ? '+' : ''}${fmtInt(change)})`;
      }
      lines.push(townLine);

      if (row.customersServed !== null) {
        let affected =
          `${fmtInt(row.customersOut)} of ${fmtInt(row.customersServed)} ` +
          `customers out`;

        if (pct) affected += ` (${pct})`;
        lines.push(affected);
      } else {
        lines.push(`${fmtInt(row.customersOut)} customers out`);
      }

      lines.push(
        `ETR ${formatTime(row.etrEarliest)} | ` +
          `Started ${formatTime(row.earliestCurrentOutage)}`
      );

      const ops = operationalLine(row);
      if (ops) lines.push(ops);

      const damage = damageLine(row);
      if (damage) lines.push(damage);

      lines.push('');
    }
  }

  lines.push('HUDSON COUNTY STATUS');

  for (const row of rows) {
    const oldRow = previousRows[row.town] ?? null;
    const wasOut = (oldRow?.customersOut ?? 0) > 0;
    const isOut = row.dataStatus === 'OK' && (row.customersOut ?? 0) > 0;

    if (row.dataStatus !== 'OK') {
      lines.push(`${row.town}: NO DATA`);
    } else if (isOut) {
      lines.push(`${statusIcon(row)} ${row.town}: ${fmtInt(row.customersOut)}`);
    } else if (previous && wasOut) {
      lines.push(`🟢 ${row.town}: 0 RESTORED`);
    } else {
      lines.push(`${row.town}: 0`);
    }
  }

  lines.push('');
  lines.push(`Updated ${nowEastern()}`);

  return lines.join('\n');
};

let priority = 4;
let tags = ['zap'];

if (totalOutages > previousTotal) {
  priority = 5;
  tags = ['warning', 'zap'];
} else if (totalOutages === 0 && previousTotal > 0) {
  priority = 4;
  tags = ['white_check_mark', 'zap'];
} else if (totalOutages < previousTotal) {
  priority = 3;
  tags = ['chart_with_downwards_trend', 'zap'];
} else if (etrChangedTowns.length > 0) {
  priority = 4;
  tags = ['clock1', 'zap'];
} else if (!previous && totalOutages > 0) {
  priority = 5;
  tags = ['warning', 'zap'];
}

const ntfyPayload = {
  topic: '[REDACTED]',
  title: buildTitle(),
  message: buildMessage(),
  priority,
  tags,
  markdown: false,
  click: PSEG_MAP_URL,
  actions: [
    {
      action: 'view',
      label: 'PSEG Map',
      url: PSEG_MAP_URL,
      clear: false,
    },
    {
      action: 'view',
      label: 'Hudson Summary',
      url: HUDSON_REPORT_URL,
      clear: false,
    },
  ],
};

return [
  {
    json: {
      shouldSend: true,
      reason: previous
        ? 'Hudson County PSE&G data changed.'
        : 'Initial baseline stored.',
      changedTowns,
      etrChangedTowns,
      totalOutages,
      previousTotal,
      delta,
      missingCount,
      rows,
      previousRows,
      activeRows,
      ntfyPayload,
    },
  },
];

const source = $input.first().json ?? {};

const rows = Array.isArray(source.rows) ? source.rows : [];
const previousRows = source.previousRows && typeof source.previousRows === 'object'
  ? source.previousRows
  : {};

const rowByTown = new Map(rows.map((row) => [row.town, row]));
const previousExists = source.reason !== 'Initial baseline stored.';

const affectedTowns = previousExists
  ? (Array.isArray(source.changedTowns) ? source.changedTowns : [])
  : rows
      .filter((row) => row.dataStatus === 'OK' && Number(row.customersOut || 0) > 0)
      .map((row) => row.town);

const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
const cyclesData = $getWorkflowStaticData('global');
const CYCLE_KEY = 'psegTownAlertCyclesV1';
const cycles = cyclesData[CYCLE_KEY] && typeof cyclesData[CYCLE_KEY] === 'object'
  ? cyclesData[CYCLE_KEY]
  : {};

const nowIso = new Date().toISOString();

function upper(value) {
  return String(value ?? '').trim().toUpperCase();
}

function slug(value) {
  return upper(value).replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function safeIso(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function fmtInt(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(n).toLocaleString('en-US') : '--';
}

function displayTime(value) {
  if (!value) return '--';
  const raw = String(value).trim();
  if (/assess|reassess|pending|unknown|not available|tbd/i.test(raw)) {
    return raw.toUpperCase();
  }
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw;
  return new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(d);
}

const alerts = [];

for (const town of [...new Set(affectedTowns)]) {
  const current = rowByTown.get(town);
  const previous = previousRows[town] || null;

  // Missing current data must never be interpreted as restoration.
  if (!current || current.dataStatus !== 'OK') continue;

  const currentOut = Number(current.customersOut || 0);
  const previousOut = Number(previous?.customersOut || 0);

  // Skip changes unrelated to an actual outage lifecycle.
  if (currentOut <= 0 && previousOut <= 0) continue;

  let eventAction;
  let status;

  if (currentOut > 0 && previousOut <= 0) {
    eventAction = 'NEW';
    status = 'ACTIVE';
  } else if (currentOut > 0 && previousOut > 0) {
    eventAction = 'UPDATE';
    status = 'ACTIVE';
  } else {
    eventAction = 'RESOLVED';
    status = 'RESOLVED';
  }

  const fallbackStart =
    current.earliestCurrentOutage ||
    previous?.earliestCurrentOutage ||
    nowIso;

  if (eventAction === 'NEW' || !cycles[town]) {
    cycles[town] = safeIso(fallbackStart) || String(fallbackStart);
  }

  const cycleValue = cycles[town] || safeIso(fallbackStart) || String(fallbackStart);
  const cycleToken = slug(cycleValue) || 'UNKNOWN';
  const alertId = `PSEG:OUTAGE:${slug(town)}:${cycleToken}`;

  let priority = 4;
  if (eventAction === 'NEW') {
    priority = 5;
  } else if (eventAction === 'RESOLVED') {
    priority = 4;
  } else if (currentOut > previousOut) {
    priority = 5;
  } else if (currentOut < previousOut) {
    priority = 3;
  } else if ((source.etrChangedTowns || []).includes(town)) {
    priority = 4;
  }

  let title;
  let message;
  let tags;

  if (eventAction === 'RESOLVED') {
    title = `PSEG - ${town} - Power Restored`;
    message =
      `Power restored in ${town}. ` +
      `${fmtInt(previousOut)} customer${previousOut === 1 ? '' : 's'} were out during the previous check.`;
    tags = ['white_check_mark', 'zap'];
  } else {
    title = `PSEG - ${town} - ${fmtInt(currentOut)} Out`;

    const parts = [];
    if (current.customersServed !== null && current.customersServed !== undefined) {
      parts.push(
        `${fmtInt(currentOut)} of ${fmtInt(current.customersServed)} customers out in ${town}.`
      );
    } else {
      parts.push(`${fmtInt(currentOut)} customers out in ${town}.`);
    }

    parts.push(`ETR ${displayTime(current.etrEarliest)}.`);
    parts.push(`Started ${displayTime(current.earliestCurrentOutage)}.`);

    const ops = [];
    if (current.numberOfJobs !== null) ops.push(`Jobs ${fmtInt(current.numberOfJobs)}`);
    if (current.jobsBeingWorked !== null) ops.push(`Working ${fmtInt(current.jobsBeingWorked)}`);
    if (current.numberOfCircuits !== null) ops.push(`Circuits ${fmtInt(current.numberOfCircuits)}`);
    if (ops.length) parts.push(ops.join(' | '));

    if (previousExists && currentOut !== previousOut) {
      const delta = currentOut - previousOut;
      parts.push(`Change ${delta > 0 ? '+' : ''}${fmtInt(delta)} since last check.`);
    }

    message = parts.join('\n');
    tags = currentOut > previousOut ? ['warning', 'zap'] : ['zap'];
  }

  const observed =
    eventAction === 'RESOLVED'
      ? (safeIso(previous?.earliestCurrentOutage) || nowIso)
      : (safeIso(current.earliestCurrentOutage) || nowIso);

  alerts.push({
    schema_version: '1.0',
    alert_id: alertId,
    source: 'PSEG',
    source_event_id: cycleToken,
    category: 'UTILITY',
    subtype: 'POWER_OUTAGE',
    status,
    event_action: eventAction,
    title,
    message,
    priority,
    county: 'HUDSON',
    municipality: upper(town),
    location: {
      label: town,
      address: '',
      state: 'NJ',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags,
    click_url: PSEG_MAP_URL,
    source_url: PSEG_MAP_URL,
    observed_at: observed,
    source_updated_at: nowIso,
    received_at: nowIso,
    expires_at: null,
    metadata: {
      customers_out: currentOut,
      previous_customers_out: previousOut,
      customers_served: current.customersServed,
      etr_earliest: current.etrEarliest,
      etr_latest: current.etrLatest,
      earliest_current_outage: current.earliestCurrentOutage,
      jobs: current.numberOfJobs,
      jobs_being_worked: current.jobsBeingWorked,
      circuits: current.numberOfCircuits,
      pending_damage: current.pendingDamage,
      confirmed_poles: current.confirmedPoles,
      confirmed_trees: current.confirmedTrees,
      confirmed_roads_blocked: current.confirmedRoadsBlocked,
      hudson_total_out: source.totalOutages,
      hudson_previous_total_out: source.previousTotal,
      hudson_delta: source.delta
    }
  });

  if (eventAction === 'RESOLVED') {
    delete cycles[town];
  }
}

cyclesData[CYCLE_KEY] = cycles;

return alerts.map((alert) => ({ json: alert }));

return $input.all().map((item) => {
  const row = item.json || {};
  const alert = row.alert && typeof row.alert === 'object' ? row.alert : {};
  return { json: { ...alert, _db: { alert_uuid: row.alert_db_uuid || null } } };
});

const response = $input.first().json ?? {};
const content = response.content ?? response;
const towns = Array.isArray(content.towns) ? content.towns : [];

if (!towns.length) {
  throw new Error(
    'PSE&G outage summary returned no town records. No notification was sent and the previous baseline was preserved.'
  );
}

const EXPECTED_TOWNS = [
  'Bayonne',
  'East Newark',
  'Guttenberg',
  'Harrison',
  'Hoboken',
  'Jersey City',
  'Kearny',
  'North Bergen',
  'Secaucus',
  'Union City',
  'Weehawken',
  'West New York',
];

const STATE_KEY = 'psegHudsonStateV5';
const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
const HUDSON_REPORT_URL =
  'https://outagecenter.pseg.com/reports/e2d9e8d8-113c-423b-af59-0de1bc440376?c=External&o=View_by_county';

const firstDefined = (...values) =>
  values.find((value) => value !== undefined && value !== null && value !== '');

const toNumber = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const toText = (value) => {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text || null;
};

const fmtInt = (value) =>
  value === null || value === undefined
    ? '--'
    : Math.round(value).toLocaleString('en-US');

const customerWord = (count) => (Number(count) === 1 ? 'customer' : 'customers');

const municipalityWord = (count) =>
  Number(count) === 1 ? 'municipality' : 'municipalities';

const normalizeTown = (value) => {
  let town = String(value ?? '')
    .toUpperCase()
    .replace(/[.,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const exact = {
    BAYONNE: 'Bayonne',
    'EAST NEWARK': 'East Newark',
    GUTTENBERG: 'Guttenberg',
    HARRISON: 'Harrison',
    HOBOKEN: 'Hoboken',
    'JERSEY CITY': 'Jersey City',
    KEARNY: 'Kearny',
    'NORTH BERGEN': 'North Bergen',
    SECAUCUS: 'Secaucus',
    'UNION CITY': 'Union City',
    WEEHAWKEN: 'Weehawken',
    'WEST NEW YORK': 'West New York',
  };

  if (exact[town]) return exact[town];

  town = town
    .replace(/\s+(TOWNSHIP|TWP|TOWN|CITY|BOROUGH|BORO|VILLAGE)$/i, '')
    .replace(/\s+/g, ' ')
    .trim();

  return (
    exact[town] ||
    town.toLowerCase().replace(/\b\w/g, (letter) => letter.toUpperCase())
  );
};

const formatTime = (value) => {
  if (!value) return '--';

  const raw = String(value).trim();
  if (!raw) return '--';

  if (/assess|reassess|pending|unknown|not available|tbd/i.test(raw)) {
    return raw.toUpperCase();
  }

  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw.toUpperCase();

  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(date);
};

const nowEastern = () =>
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(new Date());

const percentOutText = (row) => {
  const out = Number(row.customersOut);
  const served = Number(row.customersServed);

  if (!Number.isFinite(out) || !Number.isFinite(served) || served <= 0) {
    return null;
  }

  const pct = (out / served) * 100;

  if (out > 0 && pct < 0.1) return '<0.1%';
  return `${pct.toFixed(1)}%`;
};

const operationalLine = (row) => {
  const parts = [];

  if (row.numberOfJobs !== null) {
    parts.push(`Jobs ${fmtInt(row.numberOfJobs)}`);
  }

  if (row.jobsBeingWorked !== null) {
    parts.push(`Working ${fmtInt(row.jobsBeingWorked)}`);
  }

  if (row.numberOfCircuits !== null) {
    parts.push(`Circuits ${fmtInt(row.numberOfCircuits)}`);
  }

  return parts.join(' | ');
};

const damageLine = (row) => {
  const parts = [];

  const addIfPositive = (label, value) => {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) {
      parts.push(`${label} ${fmtInt(n)}`);
    }
  };

  addIfPositive('Pending', row.pendingDamage);
  addIfPositive('Pole', row.confirmedPoles);
  addIfPositive('Tree', row.confirmedTrees);
  addIfPositive('Road', row.confirmedRoadsBlocked);

  return parts.length ? `Damage: ${parts.join(' | ')}` : null;
};

const isHudsonRecord = (record) => {
  const county = String(
    firstDefined(record.county, record.displayCounty, '') ?? ''
  ).toUpperCase();

  const town = normalizeTown(
    firstDefined(record.displayTown, record.town, record.name, '')
  );

  return county.includes('HUDSON') || EXPECTED_TOWNS.includes(town);
};

const byTown = new Map();

for (const record of towns.filter(isHudsonRecord)) {
  const town = normalizeTown(
    firstDefined(record.displayTown, record.town, record.name, '')
  );

  if (EXPECTED_TOWNS.includes(town)) {
    byTown.set(town, record);
  }
}

const rows = EXPECTED_TOWNS.map((town) => {
  const record = byTown.get(town);

  if (!record) {
    return {
      town,
      dataStatus: 'NO DATA',
      customersOut: null,
      customersServed: null,
      earliestCurrentOutage: null,
      etrEarliest: null,
      etrLatest: null,
      numberOfJobs: null,
      jobsBeingWorked: null,
      numberOfCircuits: null,
      pendingDamage: null,
      confirmedPoles: null,
      confirmedTrees: null,
      confirmedRoadsBlocked: null,
    };
  }

  return {
    town,
    dataStatus: 'OK',
    customersOut: toNumber(record.customersOut),
    customersServed: toNumber(record.customersServed),
    earliestCurrentOutage: toText(record.earliestCurrentOutage),
    etrEarliest: toText(record.etrEarliest),
    etrLatest: toText(
      firstDefined(record.etrLatest, record.latestEtr, record.etrLatestTime)
    ),
    numberOfJobs: toNumber(record.numberOfJobs),
    jobsBeingWorked: toNumber(
      firstDefined(
        record.numberOfJobsBeingWorked,
        record.jobsBeingWorked,
        record.workingJobs
      )
    ),
    numberOfCircuits: toNumber(record.numberOfCircuits),
    pendingDamage: toNumber(record.pendingDamage),
    confirmedPoles: toNumber(record.confirmedPoles),
    confirmedTrees: toNumber(record.confirmedTrees),
    confirmedRoadsBlocked: toNumber(
      firstDefined(
        record.confirmedRoadsBlocked,
        record.roadsBlocked,
        record.confirmedRoads
      )
    ),
  };
});

const totalOutages = rows.reduce(
  (sum, row) => sum + (row.customersOut ?? 0),
  0
);

const missingCount = rows.filter((row) => row.dataStatus !== 'OK').length;

const currentState = {
  rows: Object.fromEntries(rows.map((row) => [row.town, row])),
  totalOutages,
  missingCount,
};

const staticData = $getWorkflowStaticData('global');
const previous = staticData[STATE_KEY] ?? null;
const previousRows = previous?.rows ?? {};
const previousTotal = Number(previous?.totalOutages ?? 0);

const changedTowns = [];
const etrChangedTowns = [];

if (previous) {
  for (const row of rows) {
    const oldRow = previousRows[row.town] ?? null;

    if (JSON.stringify(oldRow) !== JSON.stringify(row)) {
      changedTowns.push(row.town);
    }

    if (
      oldRow &&
      (oldRow.etrEarliest !== row.etrEarliest ||
        oldRow.etrLatest !== row.etrLatest)
    ) {
      etrChangedTowns.push(row.town);
    }
  }
}

const stateChanged =
  !previous ||
  changedTowns.length > 0 ||
  Number(previous?.missingCount ?? 0) !== missingCount;

// Only replace the baseline after a successful parse.
staticData[STATE_KEY] = currentState;

if (previous && !stateChanged) {
  return [
    {
      json: {
        shouldSend: false,
        reason: 'No meaningful Hudson County PSE&G data changed.',
        totalOutages,
        missingCount,
        ntfyPayload: null,
      },
    },
  ];
}

const activeRows = rows.filter(
  (row) => row.dataStatus === 'OK' && (row.customersOut ?? 0) > 0
);

const delta = previous ? totalOutages - previousTotal : 0;

const townDelta = (row) => {
  if (!previous) return 0;
  const oldRow = previousRows[row.town] ?? null;
  return (row.customersOut ?? 0) - (oldRow?.customersOut ?? 0);
};

const statusIcon = (row) => {
  if (!previous) return '🔴';

  const change = townDelta(row);

  if (change > 0) return '🔴';
  if (change < 0) return '🟡';
  if (etrChangedTowns.includes(row.town)) return '🟠';
  return '🔴';
};

const buildTitle = () => {
  if (totalOutages === 0) {
    return previousTotal > 0
      ? 'PSEG - Hudson - Power Restored'
      : 'PSEG - Hudson Clear';
  }

  if (activeRows.length === 1) {
    const row = activeRows[0];
    return `PSEG - ${row.town} - ${fmtInt(row.customersOut)} Out`;
  }

  return `PSEG - Hudson - ${fmtInt(totalOutages)} Out`;
};

const buildMessage = () => {
  const lines = [];

  if (totalOutages === 0) {
    lines.push('HUDSON COUNTY CLEAR');
    lines.push('0 customers out');

    if (previous && previousTotal > 0) {
      lines.push(`${fmtInt(previousTotal)} restored since last check`);
    }
  } else {
    lines.push(
      `${fmtInt(totalOutages)} ${customerWord(totalOutages)} out | ` +
        `${activeRows.length} active ${municipalityWord(activeRows.length)}`
    );

    if (previous && delta !== 0) {
      lines.push(`Change since last check: ${delta > 0 ? '+' : ''}${fmtInt(delta)}`);
    }

    lines.push('');

    for (const row of activeRows) {
      const pct = percentOutText(row);
      const change = townDelta(row);

      let townLine = `${statusIcon(row)} ${row.town.toUpperCase()}`;
      if (previous && change !== 0) {
        townLine += ` (${change > 0 ? '+' : ''}${fmtInt(change)})`;
      }
      lines.push(townLine);

      if (row.customersServed !== null) {
        let affected =
          `${fmtInt(row.customersOut)} of ${fmtInt(row.customersServed)} ` +
          `customers out`;

        if (pct) affected += ` (${pct})`;
        lines.push(affected);
      } else {
        lines.push(`${fmtInt(row.customersOut)} customers out`);
      }

      lines.push(
        `ETR ${formatTime(row.etrEarliest)} | ` +
          `Started ${formatTime(row.earliestCurrentOutage)}`
      );

      const ops = operationalLine(row);
      if (ops) lines.push(ops);

      const damage = damageLine(row);
      if (damage) lines.push(damage);

      lines.push('');
    }
  }

  lines.push('HUDSON COUNTY STATUS');

  for (const row of rows) {
    const oldRow = previousRows[row.town] ?? null;
    const wasOut = (oldRow?.customersOut ?? 0) > 0;
    const isOut = row.dataStatus === 'OK' && (row.customersOut ?? 0) > 0;

    if (row.dataStatus !== 'OK') {
      lines.push(`${row.town}: NO DATA`);
    } else if (isOut) {
      lines.push(`${statusIcon(row)} ${row.town}: ${fmtInt(row.customersOut)}`);
    } else if (previous && wasOut) {
      lines.push(`🟢 ${row.town}: 0 RESTORED`);
    } else {
      lines.push(`${row.town}: 0`);
    }
  }

  lines.push('');
  lines.push(`Updated ${nowEastern()}`);

  return lines.join('\n');
};

let priority = 4;
let tags = ['zap'];

if (totalOutages > previousTotal) {
  priority = 5;
  tags = ['warning', 'zap'];
} else if (totalOutages === 0 && previousTotal > 0) {
  priority = 4;
  tags = ['white_check_mark', 'zap'];
} else if (totalOutages < previousTotal) {
  priority = 3;
  tags = ['chart_with_downwards_trend', 'zap'];
} else if (etrChangedTowns.length > 0) {
  priority = 4;
  tags = ['clock1', 'zap'];
} else if (!previous && totalOutages > 0) {
  priority = 5;
  tags = ['warning', 'zap'];
}

const ntfyPayload = {
  topic: '[REDACTED]',
  title: buildTitle(),
  message: buildMessage(),
  priority,
  tags,
  markdown: false,
  click: PSEG_MAP_URL,
  actions: [
    {
      action: 'view',
      label: 'PSEG Map',
      url: PSEG_MAP_URL,
      clear: false,
    },
    {
      action: 'view',
      label: 'Hudson Summary',
      url: HUDSON_REPORT_URL,
      clear: false,
    },
  ],
};

return [
  {
    json: {
      shouldSend: true,
      reason: previous
        ? 'Hudson County PSE&G data changed.'
        : 'Initial baseline stored.',
      changedTowns,
      etrChangedTowns,
      totalOutages,
      previousTotal,
      delta,
      missingCount,
      rows,
      previousRows,
      activeRows,
      ntfyPayload,
    },
  },
];

const source = $input.first().json ?? {};

const rows = Array.isArray(source.rows) ? source.rows : [];
const previousRows = source.previousRows && typeof source.previousRows === 'object'
  ? source.previousRows
  : {};

const rowByTown = new Map(rows.map((row) => [row.town, row]));
const previousExists = source.reason !== 'Initial baseline stored.';

const affectedTowns = previousExists
  ? (Array.isArray(source.changedTowns) ? source.changedTowns : [])
  : rows
      .filter((row) => row.dataStatus === 'OK' && Number(row.customersOut || 0) > 0)
      .map((row) => row.town);

const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
const cyclesData = $getWorkflowStaticData('global');
const CYCLE_KEY = 'psegTownAlertCyclesV1';
const cycles = cyclesData[CYCLE_KEY] && typeof cyclesData[CYCLE_KEY] === 'object'
  ? cyclesData[CYCLE_KEY]
  : {};

const nowIso = new Date().toISOString();

function upper(value) {
  return String(value ?? '').trim().toUpperCase();
}

function slug(value) {
  return upper(value).replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function safeIso(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function fmtInt(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(n).toLocaleString('en-US') : '--';
}

function displayTime(value) {
  if (!value) return '--';
  const raw = String(value).trim();
  if (/assess|reassess|pending|unknown|not available|tbd/i.test(raw)) {
    return raw.toUpperCase();
  }
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw;
  return new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(d);
}

const alerts = [];

for (const town of [...new Set(affectedTowns)]) {
  const current = rowByTown.get(town);
  const previous = previousRows[town] || null;

  // Missing current data must never be interpreted as restoration.
  if (!current || current.dataStatus !== 'OK') continue;

  const currentOut = Number(current.customersOut || 0);
  const previousOut = Number(previous?.customersOut || 0);

  // Skip changes unrelated to an actual outage lifecycle.
  if (currentOut <= 0 && previousOut <= 0) continue;

  let eventAction;
  let status;

  if (currentOut > 0 && previousOut <= 0) {
    eventAction = 'NEW';
    status = 'ACTIVE';
  } else if (currentOut > 0 && previousOut > 0) {
    eventAction = 'UPDATE';
    status = 'ACTIVE';
  } else {
    eventAction = 'RESOLVED';
    status = 'RESOLVED';
  }

  const fallbackStart =
    current.earliestCurrentOutage ||
    previous?.earliestCurrentOutage ||
    nowIso;

  if (eventAction === 'NEW' || !cycles[town]) {
    cycles[town] = safeIso(fallbackStart) || String(fallbackStart);
  }

  const cycleValue = cycles[town] || safeIso(fallbackStart) || String(fallbackStart);
  const cycleToken = slug(cycleValue) || 'UNKNOWN';
  const alertId = `PSEG:OUTAGE:${slug(town)}:${cycleToken}`;

  let priority = 4;
  if (eventAction === 'NEW') {
    priority = 5;
  } else if (eventAction === 'RESOLVED') {
    priority = 4;
  } else if (currentOut > previousOut) {
    priority = 5;
  } else if (currentOut < previousOut) {
    priority = 3;
  } else if ((source.etrChangedTowns || []).includes(town)) {
    priority = 4;
  }

  let title;
  let message;
  let tags;

  if (eventAction === 'RESOLVED') {
    title = `PSEG - ${town} - Power Restored`;
    message =
      `Power restored in ${town}. ` +
      `${fmtInt(previousOut)} customer${previousOut === 1 ? '' : 's'} were out during the previous check.`;
    tags = ['white_check_mark', 'zap'];
  } else {
    title = `PSEG - ${town} - ${fmtInt(currentOut)} Out`;

    const parts = [];
    if (current.customersServed !== null && current.customersServed !== undefined) {
      parts.push(
        `${fmtInt(currentOut)} of ${fmtInt(current.customersServed)} customers out in ${town}.`
      );
    } else {
      parts.push(`${fmtInt(currentOut)} customers out in ${town}.`);
    }

    parts.push(`ETR ${displayTime(current.etrEarliest)}.`);
    parts.push(`Started ${displayTime(current.earliestCurrentOutage)}.`);

    const ops = [];
    if (current.numberOfJobs !== null) ops.push(`Jobs ${fmtInt(current.numberOfJobs)}`);
    if (current.jobsBeingWorked !== null) ops.push(`Working ${fmtInt(current.jobsBeingWorked)}`);
    if (current.numberOfCircuits !== null) ops.push(`Circuits ${fmtInt(current.numberOfCircuits)}`);
    if (ops.length) parts.push(ops.join(' | '));

    if (previousExists && currentOut !== previousOut) {
      const delta = currentOut - previousOut;
      parts.push(`Change ${delta > 0 ? '+' : ''}${fmtInt(delta)} since last check.`);
    }

    message = parts.join('\n');
    tags = currentOut > previousOut ? ['warning', 'zap'] : ['zap'];
  }

  const observed =
    eventAction === 'RESOLVED'
      ? (safeIso(previous?.earliestCurrentOutage) || nowIso)
      : (safeIso(current.earliestCurrentOutage) || nowIso);

  alerts.push({
    schema_version: '1.0',
    alert_id: alertId,
    source: 'PSEG',
    source_event_id: cycleToken,
    category: 'UTILITY',
    subtype: 'POWER_OUTAGE',
    status,
    event_action: eventAction,
    title,
    message,
    priority,
    county: 'HUDSON',
    municipality: upper(town),
    location: {
      label: town,
      address: '',
      state: 'NJ',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags,
    click_url: PSEG_MAP_URL,
    source_url: PSEG_MAP_URL,
    observed_at: observed,
    source_updated_at: nowIso,
    received_at: nowIso,
    expires_at: null,
    metadata: {
      customers_out: currentOut,
      previous_customers_out: previousOut,
      customers_served: current.customersServed,
      etr_earliest: current.etrEarliest,
      etr_latest: current.etrLatest,
      earliest_current_outage: current.earliestCurrentOutage,
      jobs: current.numberOfJobs,
      jobs_being_worked: current.jobsBeingWorked,
      circuits: current.numberOfCircuits,
      pending_damage: current.pendingDamage,
      confirmed_poles: current.confirmedPoles,
      confirmed_trees: current.confirmedTrees,
      confirmed_roads_blocked: current.confirmedRoadsBlocked,
      hudson_total_out: source.totalOutages,
      hudson_previous_total_out: source.previousTotal,
      hudson_delta: source.delta
    }
  });

  if (eventAction === 'RESOLVED') {
    delete cycles[town];
  }
}

cyclesData[CYCLE_KEY] = cycles;

return alerts.map((alert) => ({ json: alert }));

return $input.all().map((item) => {
  const row = item.json || {};
  const alert = row.alert && typeof row.alert === 'object' ? row.alert : {};
  return { json: { ...alert, _db: { alert_uuid: row.alert_db_uuid || null } } };
});

const response = $input.first().json ?? {};
const content = response.content ?? response;
const towns = Array.isArray(content.towns) ? content.towns : [];

if (!towns.length) {
  throw new Error('PSE&G outage summary returned no town records.');
}

// -----------------------------------------------------------------------------
// CONFIG
// -----------------------------------------------------------------------------
const HUDSON_TOWNS = [
  'Bayonne',
  'East Newark',
  'Guttenberg',
  'Harrison',
  'Hoboken',
  'Jersey City',
  'Kearny',
  'North Bergen',
  'Secaucus',
  'Union City',
  'Weehawken',
  'West New York',
];

const STATE_KEY = 'psegHudsonStateV5';
const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
const HUDSON_REPORT_URL =
  'https://outagecenter.pseg.com/reports/e2d9e8d8-113c-423b-af59-0de1bc440376?c=External&o=View_by_county';

// -----------------------------------------------------------------------------
// HELPERS
// -----------------------------------------------------------------------------
const pick = (...values) =>
  values.find(v => v !== undefined && v !== null && v !== '');

const numberOrNull = value => {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const textOrNull = value => {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text || null;
};

const fmt = value =>
  value === null || value === undefined
    ? '--'
    : Math.round(value).toLocaleString('en-US');

const plural = (count, singular, pluralForm = `${singular}s`) =>
  Number(count) === 1 ? singular : pluralForm;

const easternTime = date =>
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(date);

const formatTime = value => {
  if (!value) return '--';

  const raw = String(value).trim();
  if (!raw) return '--';

  if (/assess|reassess|pending|unknown|not available|tbd/i.test(raw)) {
    return raw.toUpperCase();
  }

  const date = new Date(raw);
  return Number.isNaN(date.getTime()) ? raw.toUpperCase() : easternTime(date);
};

const normalizeTown = value => {
  const aliases = {
    BAYONNE: 'Bayonne',
    'EAST NEWARK': 'East Newark',
    GUTTENBERG: 'Guttenberg',
    HARRISON: 'Harrison',
    HOBOKEN: 'Hoboken',
    'JERSEY CITY': 'Jersey City',
    KEARNY: 'Kearny',
    'NORTH BERGEN': 'North Bergen',
    SECAUCUS: 'Secaucus',
    'UNION CITY': 'Union City',
    WEEHAWKEN: 'Weehawken',
    'WEST NEW YORK': 'West New York',
  };

  let town = String(value ?? '')
    .toUpperCase()
    .replace(/[.,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (aliases[town]) return aliases[town];

  town = town
    .replace(/\s+(TOWNSHIP|TWP|TOWN|CITY|BOROUGH|BORO|VILLAGE)$/i, '')
    .replace(/\s+/g, ' ')
    .trim();

  return aliases[town] ??
    town.toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase());
};

const percentOut = row => {
  const out = Number(row.customersOut);
  const served = Number(row.customersServed);

  if (!Number.isFinite(out) || !Number.isFinite(served) || served <= 0) {
    return null;
  }

  const pct = (out / served) * 100;
  return out > 0 && pct < 0.1 ? '<0.1%' : `${pct.toFixed(1)}%`;
};

const etrText = row => {
  const earliest = formatTime(row.etrEarliest);
  const latest = formatTime(row.etrLatest);

  if (
    earliest !== '--' &&
    latest !== '--' &&
    earliest !== latest
  ) {
    return `${earliest}-${latest}`;
  }

  return earliest !== '--' ? earliest : latest;
};

// -----------------------------------------------------------------------------
// NORMALIZE HUDSON COUNTY DATA
// -----------------------------------------------------------------------------
const recordsByTown = new Map();

for (const record of towns) {
  const county = String(
    pick(record.county, record.displayCounty, '') ?? ''
  ).toUpperCase();

  const town = normalizeTown(
    pick(record.displayTown, record.town, record.name, '')
  );

  if (
    HUDSON_TOWNS.includes(town) &&
    (county.includes('HUDSON') || HUDSON_TOWNS.includes(town))
  ) {
    recordsByTown.set(town, record);
  }
}

const rows = HUDSON_TOWNS.map(town => {
  const record = recordsByTown.get(town);

  if (!record) {
    return {
      town,
      dataStatus: 'NO DATA',
      customersOut: null,
      customersServed: null,
      earliestCurrentOutage: null,
      etrEarliest: null,
      etrLatest: null,
      numberOfJobs: null,
      jobsBeingWorked: null,
      numberOfCircuits: null,
      pendingDamage: null,
      confirmedPoles: null,
      confirmedTrees: null,
      confirmedRoadsBlocked: null,
    };
  }

  return {
    town,
    dataStatus: 'OK',
    customersOut: numberOrNull(record.customersOut),
    customersServed: numberOrNull(record.customersServed),
    earliestCurrentOutage: textOrNull(record.earliestCurrentOutage),
    etrEarliest: textOrNull(record.etrEarliest),
    etrLatest: textOrNull(
      pick(record.etrLatest, record.latestEtr, record.etrLatestTime)
    ),
    numberOfJobs: numberOrNull(record.numberOfJobs),
    jobsBeingWorked: numberOrNull(
      pick(
        record.numberOfJobsBeingWorked,
        record.jobsBeingWorked,
        record.workingJobs
      )
    ),
    numberOfCircuits: numberOrNull(record.numberOfCircuits),
    pendingDamage: numberOrNull(record.pendingDamage),
    confirmedPoles: numberOrNull(record.confirmedPoles),
    confirmedTrees: numberOrNull(record.confirmedTrees),
    confirmedRoadsBlocked: numberOrNull(
      pick(
        record.confirmedRoadsBlocked,
        record.roadsBlocked,
        record.confirmedRoads
      )
    ),
  };
});

// -----------------------------------------------------------------------------
// COMPARE WITH PREVIOUS RUN
// -----------------------------------------------------------------------------
const totalOutages = rows.reduce(
  (sum, row) => sum + (row.customersOut ?? 0),
  0
);

const missingCount = rows.filter(row => row.dataStatus !== 'OK').length;

const currentState = {
  rows: Object.fromEntries(rows.map(row => [row.town, row])),
  totalOutages,
  missingCount,
};

const staticData = $getWorkflowStaticData('global');
const previous = staticData[STATE_KEY] ?? null;
const previousRows = previous?.rows ?? {};
const previousTotal = Number(previous?.totalOutages ?? 0);

const changedTowns = [];
const etrChangedTowns = [];

if (previous) {
  for (const row of rows) {
    const oldRow = previousRows[row.town] ?? null;

    if (JSON.stringify(oldRow) !== JSON.stringify(row)) {
      changedTowns.push(row.town);
    }

    if (
      oldRow &&
      (
        oldRow.etrEarliest !== row.etrEarliest ||
        oldRow.etrLatest !== row.etrLatest
      )
    ) {
      etrChangedTowns.push(row.town);
    }
  }
}

const stateChanged =
  !previous ||
  changedTowns.length > 0 ||
  Number(previous?.missingCount ?? 0) !== missingCount;

staticData[STATE_KEY] = currentState;

if (previous && !stateChanged) {
  return [{
    json: {
      shouldSend: false,
      reason: 'No meaningful Hudson County PSE&G data changed.',
      totalOutages,
      missingCount,
      ntfyPayload: null,
    },
  }];
}

// -----------------------------------------------------------------------------
// BUILD ALERT
// -----------------------------------------------------------------------------
const activeRows = rows.filter(
  row => row.dataStatus === 'OK' && (row.customersOut ?? 0) > 0
);

const delta = previous ? totalOutages - previousTotal : 0;

const townDelta = row => {
  if (!previous) return 0;
  const old = previousRows[row.town]?.customersOut ?? 0;
  return (row.customersOut ?? 0) - old;
};

const restored = rows
  .filter(row => {
    const wasOut = (previousRows[row.town]?.customersOut ?? 0) > 0;
    const isOut = row.dataStatus === 'OK' && (row.customersOut ?? 0) > 0;
    return previous && wasOut && !isOut;
  })
  .map(row => row.town);

const noData = rows
  .filter(row => row.dataStatus !== 'OK')
  .map(row => row.town);

const buildTitle = () => {
  if (totalOutages === 0) {
    return previousTotal > 0
      ? 'PSEG - Hudson - Power Restored'
      : 'PSEG - Hudson Clear';
  }

  if (activeRows.length === 1) {
    const row = activeRows[0];
    return `PSEG - ${row.town} - ${fmt(row.customersOut)} Out`;
  }

  return `PSEG - Hudson - ${fmt(totalOutages)} Out`;
};

const buildMessage = () => {
  const lines = [];

  if (totalOutages === 0) {
    lines.push('✅ **HUDSON COUNTY CLEAR**');
    lines.push('0 customers out');

    if (previous && previousTotal > 0) {
      lines.push(`${fmt(previousTotal)} restored since last check`);
    }

    if (noData.length) {
      lines.push('');
      lines.push(`⚠️ No data: ${noData.join(', ')}`);
    }

    lines.push('');
    lines.push(`Updated ${easternTime(new Date())}`);
    return lines.join('\n');
  }

  lines.push(
    `⚡ **${fmt(totalOutages)} ${plural(totalOutages, 'customer')} out** | ` +
    `${activeRows.length} active ${plural(activeRows.length, 'municipality', 'municipalities')}`
  );

  if (previous && delta !== 0) {
    lines.push(`Change since last check: ${delta > 0 ? '+' : ''}${fmt(delta)}`);
  }

  for (const row of activeRows) {
    lines.push('');

    const pct = percentOut(row);
    const change = townDelta(row);

    let townLine =
      `🔴 **${row.town.toUpperCase()}** — ${fmt(row.customersOut)}`;

    if (row.customersServed !== null) {
      townLine += ` of ${fmt(row.customersServed)}`;
    }

    if (pct) townLine += ` (${pct})`;

    if (previous && change !== 0) {
      townLine += `  [${change > 0 ? '+' : ''}${fmt(change)}]`;
    }

    lines.push(townLine);

    const timing = [];
    const etr = etrText(row);
    if (etr !== '--') timing.push(`ETR ${etr}`);

    const started = formatTime(row.earliestCurrentOutage);
    if (started !== '--') timing.push(`Started ${started}`);

    if (timing.length) {
      lines.push(timing.join(' | '));
    }

    const operations = [];
    if (row.numberOfJobs !== null) {
      operations.push(`Jobs ${fmt(row.numberOfJobs)}`);
    }
    if (row.jobsBeingWorked !== null) {
      operations.push(`Working ${fmt(row.jobsBeingWorked)}`);
    }
    if (row.numberOfCircuits !== null) {
      operations.push(`Circuits ${fmt(row.numberOfCircuits)}`);
    }

    if (operations.length) {
      lines.push(operations.join(' | '));
    }

    const damage = [];
    if ((row.pendingDamage ?? 0) > 0) {
      damage.push(`Pending ${fmt(row.pendingDamage)}`);
    }
    if ((row.confirmedPoles ?? 0) > 0) {
      damage.push(`Poles ${fmt(row.confirmedPoles)}`);
    }
    if ((row.confirmedTrees ?? 0) > 0) {
      damage.push(`Trees ${fmt(row.confirmedTrees)}`);
    }
    if ((row.confirmedRoadsBlocked ?? 0) > 0) {
      damage.push(`Roads ${fmt(row.confirmedRoadsBlocked)}`);
    }

    if (damage.length) {
      lines.push(`Damage: ${damage.join(' | ')}`);
    }
  }

  if (restored.length) {
    lines.push('');
    lines.push(`✅ Restored: ${restored.join(', ')}`);
  }

  if (noData.length) {
    lines.push('');
    lines.push(`⚠️ No data: ${noData.join(', ')}`);
  }

  lines.push('');
  lines.push(`Updated ${easternTime(new Date())}`);

  return lines.join('\n').trim();
};

// -----------------------------------------------------------------------------
// NTFY PRIORITY / TAGS
// -----------------------------------------------------------------------------
let priority = 4;
let tags = ['zap'];

if (totalOutages > previousTotal) {
  priority = 5;
  tags = ['warning', 'zap'];
} else if (totalOutages === 0 && previousTotal > 0) {
  priority = 4;
  tags = ['white_check_mark', 'zap'];
} else if (totalOutages < previousTotal) {
  priority = 3;
  tags = ['chart_with_downwards_trend', 'zap'];
} else if (etrChangedTowns.length > 0) {
  priority = 4;
  tags = ['clock1', 'zap'];
} else if (!previous && totalOutages > 0) {
  priority = 5;
  tags = ['warning', 'zap'];
}

const ntfyPayload = {
  topic: '[REDACTED]',
  title: buildTitle(),
  message: buildMessage(),
  priority,
  tags,
  markdown: true,
  click: PSEG_MAP_URL,
  actions: [
    {
      action: 'view',
      label: 'PSEG Map',
      url: PSEG_MAP_URL,
      clear: false,
    },
    {
      action: 'view',
      label: 'Hudson Summary',
      url: HUDSON_REPORT_URL,
      clear: false,
    },
  ],
};

return [{
  json: {
    shouldSend: true,
    reason: previous
      ? 'Hudson County PSE&G data changed.'
      : 'Initial baseline stored.',
    changedTowns,
    etrChangedTowns,
    totalOutages,
    previousTotal,
    delta,
    missingCount,
    ntfyPayload,
  },
}];

const response = $input.first().json ?? {};
  const content = response.content ?? response;
  const towns = Array.isArray(content.towns) ? content.towns : [];

  if (!towns.length) {
    throw new Error('PSE&G outage summary returned no town records. State was not changed.');
  }

  const HUDSON_TOWNS = [
    'Bayonne', 'East Newark', 'Guttenberg', 'Harrison', 'Hoboken',
    'Jersey City', 'Kearny', 'North Bergen', 'Secaucus', 'Union City',
    'Weehawken', 'West New York',
  ];

  const STATE_KEY = 'psegHudsonStateV6';
  const LEGACY_STATE_KEY = 'psegHudsonStateV5';

  const pick = (...values) => values.find(v => v !== undefined && v !== null && v !== '');
  const numberOrNull = value => {
    if (value === undefined || value === null || value === '') return null;
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
  };
  const textOrNull = value => {
    if (value === undefined || value === null) return null;
    const text = String(value).trim();
    return text || null;
  };
  const normalizeTown = value => {
    const aliases = {
      BAYONNE: 'Bayonne',
      'EAST NEWARK': 'East Newark',
      GUTTENBERG: 'Guttenberg',
      HARRISON: 'Harrison',
      HOBOKEN: 'Hoboken',
      'JERSEY CITY': 'Jersey City',
      KEARNY: 'Kearny',
      'NORTH BERGEN': 'North Bergen',
      SECAUCUS: 'Secaucus',
      'UNION CITY': 'Union City',
      WEEHAWKEN: 'Weehawken',
      'WEST NEW YORK': 'West New York',
    };

    let town = String(value ?? '')
      .toUpperCase()
      .replace(/[.,]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    if (aliases[town]) return aliases[town];

    town = town
      .replace(/\s+(TOWNSHIP|TWP|TOWN|CITY|BOROUGH|BORO|VILLAGE)$/i, '')
      .replace(/\s+/g, ' ')
      .trim();

    return aliases[town] ?? town.toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase());
  };

  const recordsByTown = new Map();
  for (const record of towns) {
    const county = String(pick(record.county, record.displayCounty, '') ?? '').toUpperCase();
    const town = normalizeTown(pick(record.displayTown, record.town, record.name, ''));

    const countyMatches = county ? county.includes('HUDSON') : true;
    if (HUDSON_TOWNS.includes(town) && countyMatches) {
      recordsByTown.set(town, record);
    }
  }

  const rows = HUDSON_TOWNS.map(town => {
    const record = recordsByTown.get(town);
    if (!record) {
      return {
        town,
