    const encodedPoint = geom?.p?.[0];
    if (encodedPoint) {
      const point = decodePolyline(encodedPoint)[0];
      if (point) return { latitude: point[0], longitude: point[1], geometryType: 'point' };
    }

    const encodedArea = geom?.a?.[0];
    if (encodedArea) {
      const points = decodePolyline(encodedArea);
      if (points.length) {
        const latitude = points.reduce((sum, point) => sum + point[0], 0) / points.length;
        const longitude = points.reduce((sum, point) => sum + point[1], 0) / points.length;
        return { latitude, longitude, geometryType: 'area-center' };
