    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? raw.toUpperCase() : easternTime(date);
  };
  const normalizeTown = value => {
    const aliases = {
      BAYONNE: 'Bayonne', 'EAST NEWARK': 'East Newark', GUTTENBERG: 'Guttenberg',
      HARRISON: 'Harrison', HOBOKEN: 'Hoboken', 'JERSEY CITY': 'Jersey City',
      KEARNY: 'Kearny', 'NORTH BERGEN': 'North Bergen', SECAUCUS: 'Secaucus',
      'UNION CITY': 'Union City', WEEHAWKEN: 'Weehawken', 'WEST NEW YORK': 'West New York',
    };
    let text = String(value ?? '').toUpperCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
    if (aliases[text]) return aliases[text];
    text = text.replace(/\s+(TOWNSHIP|TWP|TOWN|CITY|BOROUGH|BORO|VILLAGE)$/i, '').replace(/\s+/g, ' ').trim();
    return aliases[text] ?? text.toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase());
  };
  const shortenStreet = value => String(value ?? '')
    .replace(/\bAvenue\b/gi, 'Ave')
    .replace(/\bStreet\b/gi, 'St')
    .replace(/\bBoulevard\b/gi, 'Blvd')
    .replace(/\bRoad\b/gi, 'Rd')
    .replace(/\bTerrace\b/gi, 'Ter')
    .replace(/\bPlace\b/gi, 'Pl')
    .replace(/\bLane\b/gi, 'Ln')
    .replace(/\bDrive\b/gi, 'Dr')
    .replace(/\bCourt\b/gi, 'Ct')
    .replace(/\bParkway\b/gi, 'Pkwy')
