const context = $('Analyze Hudson Summary').first().json;
  const previous = context.previous ?? null;

  const fmt = value => value === null || value === undefined
    ? '--'
    : Math.round(value).toLocaleString('en-US');
  const plural = (count, singular, pluralForm = `${singular}s`) => Number(count) === 1 ? singular : pluralForm;
  const easternTime = date => new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(date);
  const formatTime = value => {
    if (!value) return 'ASSESSING';
