    if (!raw || /^ETR-|assess|reassess|pending|unknown|not available|tbd/i.test(raw)) return 'ASSESSING';
    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? raw.toUpperCase() : easternTime(date);
  };

  const PSEG_MAP_URL = 'https://outagecenter.pseg.com/';
  const HUDSON_REPORT_URL = 'https://outagecenter.pseg.com/reports/e2d9e8d8-113c-423b-af59-0de1bc440376?c=External&o=View_by_county';
  const lines = [];
  let title;
  let finalState;

  if (!context.hasActiveOutages) {
