    lines.push('✅ **HUDSON COUNTY CLEAR**');
    lines.push('No customers are currently reported out.');
    if (context.previous && context.previousTotal > 0) {
      lines.push(`${fmt(context.previousTotal)} ${plural(context.previousTotal, 'customer')} restored since the previous alert.`);
    }
