      : `PSEG | Hudson | ${fmt(context.totalOutages)} Out`;

    lines.push(`⚡ **${fmt(context.totalOutages)} ${plural(context.totalOutages, 'customer')} out** • ${context.activeRows.length} active ${plural(context.activeRows.length, 'municipality', 'municipalities')}`);
    if (context.previous && context.delta !== 0) {
      lines.push(`Change since last alert: ${context.delta > 0 ? '+' : ''}${fmt(context.delta)}`);
    }

    for (const row of context.activeRows) {
      lines.push('');
      lines.push(`**${row.town.toUpperCase()} — ${fmt(row.customersOut)} out**`);
      const earliest = formatTime(row.etrEarliest);
      const latest = formatTime(row.etrLatest);
      if (earliest !== 'ASSESSING' && latest !== 'ASSESSING' && earliest !== latest) lines.push(`ETR ${earliest}-${latest}`);
      else if (earliest !== 'ASSESSING') lines.push(`ETR ${earliest}`);
      else if (latest !== 'ASSESSING') lines.push(`ETR ${latest}`);

      const operations = [];
      if (row.numberOfJobs !== null) operations.push(`Jobs ${fmt(row.numberOfJobs)}`);
      if (row.jobsBeingWorked !== null) operations.push(`Working ${fmt(row.jobsBeingWorked)}`);
