      lines.push(`✅ Restored: ${context.restored.join(', ')}`);
    }
    if (context.noData.length) {
      lines.push('');
      lines.push(`⚠️ No data: ${context.noData.join(', ')}`);
    }

    lines.push('');
    lines.push('📍 Approximate location details are temporarily unavailable; the summary alert remains valid.');

    const expectedJobs = context.activeRows.reduce(
      (sum, row) => sum + Math.max(1, Number(row.numberOfJobs ?? 1)),
      0,
    );
    finalState = {
      ...context.currentState,
      detailSignature: previous?.detailSignature ?? null,
      incidents: previous?.incidents ?? [],
      locationPending: true,
      locationMissingCount: Math.max(1, expectedJobs),
    };
