  }
  alerts.push({
    schema_version:'1.0', alert_id, source:'PSEG', source_event_id:cycleToken,
    category:'UTILITY', subtype:'POWER_OUTAGE', status, event_action, title, message, priority,
    county:'HUDSON', municipality:upper(town),
    location:{label:town,address:'',state:'NJ',zip:'',latitude:null,longitude:null,block:'',lot:'',qualifier:'',parcel_id:''},
    tags, click_url:PSEG_MAP_URL, source_url:PSEG_MAP_URL,
    observed_at:start, source_updated_at:nowIso, received_at:nowIso, expires_at:null,
    metadata:{test:true,customers_out:currentOut,previous_customers_out:previousOut,customers_served:current.customersServed,etr_earliest:current.etrEarliest,jobs:current.numberOfJobs,jobs_being_worked:current.jobsBeingWorked,circuits:current.numberOfCircuits}
  });
}
return alerts.map(alert => ({json: alert}));
